// Nrm2BatchedEx BLAS_EX API
//
// nrm2_batched_ex computes the euclidean norm over a batch of real or complex vectors.
//
// result := sqrt( x_i'*x_i ) for real vectors x, for i = 1, ..., batch_count
// result := sqrt( x_i**H*x_i ) for complex vectors x, for i = 1, ..., batch_count
//
// Currently supported datatypes are as follows:
//
// -------------------------------------
// | x_type | result | execution_type |
// |---------|--------|----------------|
// | bf16_r | bf16_r| f32_r |
// | f16_r | f16_r | f32_r |
// | f32_r | f32_r | f32_r |
// | f64_r | f64_r | f64_r |
// | f32_c | f32_r | f32_r |
// | f64_c | f64_r | f64_r |
// -------------------------------------
//
// Wraps rocblas_nrm2_batched_ex.
func (h Handle) Nrm2BatchedEx(n Int, x uintptr, xType Datatype, incx Int, batchCount Int, results uintptr, resultType Datatype, executionType Datatype) error {
	return Nrm2BatchedEx(h, n, x, xType, incx, batchCount, results, resultType, executionType)
}

