// Scalars a, b, c, and s may be stored in either host or device memory, location is specified by
// calling [Handle.SetPointerMode]. The computation uses the formulas
//
// sigma = sgn(a) if |a| > |b|
// = sgn(b) if |b| >= |a|
// r = sigma*sqrt( a**2 + b**2 )
// c = 1; s = 0 if r = 0
// c = a/r; s = b/r if r != 0
//
// # The subroutine also computes
//
// z = s if |a| > |b|,
// = 1/c if |b| >= |a| and c != 0
// = 1 if c = 0
//
// This allows c and s to be reconstructed from z as follows:
//
// If z = 1, set c = 0, s = 1.
// If |z| < 1, set c = sqrt(1 - z**2) and s = z.
// If |z| > 1, set c = 1/z and s = sqrt( 1 - c**2).
//
// Wraps rocblas_srotg.
func (h Handle) Srotg(a *float32, b *float32, c *float32, s *float32) error {
	return Srotg(h, a, b, c, s)
}

